5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create-owner request with a 409 (via {@code DuplicateHouseholdExceptionHandler}) when
11	 * another owner already shares the household — the same last name and the same address, compared
12	 * case-insensitively after collapsing runs of whitespace. A request that sets {@code sharesHousehold}
13	 * true opts out of the check and is allowed. The new owner is not persisted yet, so every match found
14	 * is another owner.
15	 */
16	public class RequireUniqueHousehold {
17	
18	    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        if (Boolean.TRUE.equals(owner.getSharesHousehold())) {
21	            return;
22	        }
23	        HouseholdKey household = HouseholdKey.of(owner.getLastName(), owner.getAddress());
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (household.matches(existing)) {
26	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
27	            }
28	        }
29	    }
30	}
